/// <summary>
/// PricingAttribute of table <c>InventDim</c> field inventSerialId.
/// </summary>
/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesLine, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventDiminventSerialId extends UPSPricingAttributeInventDim implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, inventSerialId);
}

public Set getAllowedValues()
{
    var       ret = new Set(Types::String);
    InventDim inventDim;

    while select inventDim
        group by inventSerialId
    {
        if (! ret.in(inventDim.inventSerialId))
        {
            ret.add(inventDim.inventSerialId);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, inventSerialId));
    qbr.value(queryValue(_value));
}
